package com.hotel.hotel_backend.controller;
import com.hotel.hotel_backend.config.JwtService;import com.hotel.hotel_backend.dto.*;import com.hotel.hotel_backend.model.User;import com.hotel.hotel_backend.repository.UserRepository;
import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users") public class UserController {
 private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;
 public UserController(UserRepository users,PasswordEncoder encoder,JwtService jwt){this.users=users;this.encoder=encoder;this.jwt=jwt;}
 @PostMapping("/signup") public ResponseEntity<?> signup(@Valid @RequestBody AuthRequest req){String email=req.email().trim().toLowerCase();if(users.findByEmail(email).isPresent())return ResponseEntity.badRequest().body(Map.of("message","Email already registered"));String role="OWNER".equalsIgnoreCase(req.role())?"OWNER":"USER";User u=new User();u.setName(req.name().trim());u.setEmail(email);u.setPhone(req.phone());u.setPassword(encoder.encode(req.password()));u.setRole(role);users.save(u);return ResponseEntity.status(201).body(authResponse(u));}
 @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody LoginRequest req){Optional<User> found=users.findByEmail(req.email().trim().toLowerCase());if(found.isEmpty())return ResponseEntity.status(401).body(Map.of("message","Invalid email or password"));User user=found.get();String stored=user.getPassword();boolean valid=stored!=null&&(stored.startsWith("$2a$")||stored.startsWith("$2b$")||stored.startsWith("$2y$"))?encoder.matches(req.password(),stored):stored!=null&&stored.equals(req.password());if(!valid)return ResponseEntity.status(401).body(Map.of("message","Invalid email or password"));if (stored != null && !(stored.startsWith("$2a$") || stored.startsWith("$2b$") || stored.startsWith("$2y$"))) { user.setPassword(encoder.encode(req.password())); users.save(user); }return ResponseEntity.ok(authResponse(user));}
 @GetMapping("/me") public ResponseEntity<?> me(org.springframework.security.core.Authentication auth){if(auth==null)return ResponseEntity.status(401).build();Optional<User> found=users.findByEmail(auth.getName());if(found.isEmpty())return ResponseEntity.notFound().build();return ResponseEntity.ok(profile(found.get()));}
 private Map<String,Object> authResponse(User u){Map<String,Object> m=profile(u);m.put("token",jwt.generate(u.getEmail(),u.getRole()));return m;}
 private Map<String,Object> profile(User u){Map<String,Object> m=new LinkedHashMap<>();m.put("id",u.getId());m.put("name",u.getName());m.put("email",u.getEmail());m.put("phone",u.getPhone());m.put("role",u.getRole());return m;}
}
